import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function InfluencerPosts() {
    const navigate = useNavigate();
    const [posts, setPosts] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadInfluencerPosts();
    }, []);

    const loadInfluencerPosts = async () => {
        try {
            setLoading(true);
            const response = await ApiService.getInfluencerReels();
            
            if (response.success) {
                setPosts(response.data || []);
            } else {
                toast.error(response.message || 'Failed to load posts');
                setPosts([]);
            }
        } catch (error) {
            console.error('Error loading posts:', error);
            toast.error('Failed to load posts: ' + (error.message || 'Unknown error'));
            setPosts([]);
        } finally {
            setLoading(false);
        }
    };

    const handleViewReel = (reelId) => {
        // Open the reel details page
        navigate(`/studio/influencer/upload/${reelId}/details`);
    };

    const handleEditReel = (reelId) => {
        // Open the edit reel page
        navigate(`/studio/influencer/upload/${reelId}`);
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Posts</h4>
                    <button 
                        className="btn btn-outline-secondary"
                        onClick={() => navigate('/studio/influencer/profile')}
                    >
                        <i className="ri-arrow-left-line me-1"></i> Back to Profile
                    </button>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border text-primary" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                                <p className="mt-2">Loading posts...</p>
                            </div>
                        ) : posts.length === 0 ? (
                            <div className="text-center py-5">
                                <i className="ri-image-line ri-3x text-muted"></i>
                                <h5 className="mt-3">No posts found</h5>
                                <p className="text-muted">You haven't uploaded any reels yet.</p>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-centered table-nowrap mb-0">
                                    <thead className="table-light">
                                        <tr>
                                            <th>Thumbnail</th>
                                            <th>Title</th>
                                            <th>Products</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Status</th>
                                            <th>Action</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {posts.map((post) => (
                                            <tr key={post.id}>
                                                <td>
                                                    {post.thumbnail ? (
                                                        <img 
                                                            src={post.thumbnail} 
                                                            alt={post.title} 
                                                            className="rounded avatar-sm"
                                                            style={{ objectFit: 'cover' }}
                                                        />
                                                    ) : (
                                                        <div className="avatar-sm bg-light rounded d-flex align-items-center justify-content-center">
                                                            <i className="ri-image-line text-muted"></i>
                                                        </div>
                                                    )}
                                                </td>
                                                <td>
                                                    <h6 className="mb-0">{post.title || 'Untitled'}</h6>
                                                </td>
                                                <td>
                                                    <span className="badge bg-primary">
                                                        {post.products ? post.products.length : 0} Products
                                                    </span>
                                                </td>
                                                <td>
                                                    <span className="text-muted">{post.views || 0}</span>
                                                </td>
                                                <td>
                                                    <span className="text-muted">{post.likes || 0}</span>
                                                </td>
                                                <td>
                                                    <span className={`badge ${
                                                        post.status === 'approved' ? 'bg-success' : 
                                                        post.status === 'pending' ? 'bg-warning' : 
                                                        'bg-danger'
                                                    }`}>
                                                        {post.status || 'unknown'}
                                                    </span>
                                                </td>
                                                <td>
                                                    <div className="d-flex gap-1">
                                                        <button
                                                            type="button"
                                                            className="btn btn-sm btn-soft-info"
                                                            onClick={() => handleViewReel(post.id)}
                                                        >
                                                            <i className="ri-eye-line"></i>
                                                        </button>
                                                        <button
                                                            type="button"
                                                            className="btn btn-sm btn-soft-primary"
                                                            onClick={() => handleEditReel(post.id)}
                                                        >
                                                            <i className="ri-edit-line"></i>
                                                        </button>
                                                    </div>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
